<?php
declare(strict_types=1);
function ensure_v17_schema(PDO $p):void{static $done=false;if($done)return;foreach([['users','is_private','TINYINT(1) NOT NULL DEFAULT 0'],['users','replay_visibility',"VARCHAR(20) NOT NULL DEFAULT 'private'"],['clips','playback_key','VARCHAR(1000) DEFAULT NULL'],['recordings','playback_key','VARCHAR(1000) DEFAULT NULL'],['feed_posts','playback_key','VARCHAR(1000) DEFAULT NULL'],['gift_events','recording_id','BIGINT UNSIGNED DEFAULT NULL']] as [$t,$c,$type])if(!v14_column_exists($p,$t,$c))$p->exec("ALTER TABLE $t ADD COLUMN $c $type");
$p->exec("CREATE TABLE IF NOT EXISTS mutation_receipts(user_id BIGINT UNSIGNED NOT NULL,request_key VARCHAR(80) NOT NULL,operation VARCHAR(40) NOT NULL,payload_hash CHAR(64) NOT NULL,response_json LONGTEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,request_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS follow_requests(requester_user_id BIGINT UNSIGNED NOT NULL,target_user_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(requester_user_id,target_user_id),KEY idx_target(target_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$p->exec("INSERT INTO buff_install_state(id,version) VALUES (1,'17.0.0') ON DUPLICATE KEY UPDATE version=VALUES(version)");$done=true;}
function v17_query(string $sql,array $args=[]):PDOStatement{$s=db()->prepare($sql);$s->execute($args);return $s;}
function v17_key(array $d):string{$k=(string)($d['requestId']??'');if(!preg_match('/^[a-zA-Z0-9_-]{16,80}$/D',$k))json_response(['message'=>'Sayfayı yenileyip işlemi tekrar deneyin.'],400);return $k;}
function v17_begin(int $id,string $key,string $op,array $payload):?array{$p=db();$hash=hash('sha256',json_encode($payload));$p->beginTransaction();v17_query('INSERT IGNORE INTO mutation_receipts(user_id,request_key,operation,payload_hash) VALUES (?,?,?,?)',[$id,$key,$op,$hash]);$r=v17_query('SELECT * FROM mutation_receipts WHERE user_id=? AND request_key=? FOR UPDATE',[$id,$key])->fetch();if(!$r||$r['operation']!==$op||$r['payload_hash']!==$hash){$p->rollBack();json_response(['message'=>'Bu işlem kimliği başka bir istekte kullanılmış.'],409);}if($r['response_json']!==null){$p->commit();$d=json_decode($r['response_json'],true);$d['duplicate']=true;return $d;}return null;}
function v17_finish(int $id,string $key,array $d):void{v17_query('UPDATE mutation_receipts SET response_json=? WHERE user_id=? AND request_key=?',[json_encode($d,JSON_UNESCAPED_UNICODE),$id,$key]);db()->commit();}
function v17_profile_sql(string $owner,int $viewer):string{return "($owner=$viewer OR EXISTS(SELECT 1 FROM users pu WHERE pu.id=$owner AND pu.is_private=0) OR EXISTS(SELECT 1 FROM follows pf WHERE pf.followed_user_id=$owner AND pf.follower_user_id=$viewer))";}
function v17_can_view_profile(int $id,?array $viewer):bool{return (bool)v17_query('SELECT 1 FROM users WHERE id=? AND '.v17_profile_sql('users.id',(int)($viewer['id']??0)),[$id])->fetchColumn();}
function v17_content(string $kind,int $id,?array $viewer):array{$types=['recording'=>['recordings','user_id'],'clip'=>['clips','created_by_user_id'],'post'=>['feed_posts','user_id']];if(!isset($types[$kind]))json_response(['message'=>'İçerik bulunamadı.'],404);[$table,$col]=$types[$kind];$r=v17_query("SELECT * FROM $table WHERE id=?",[$id])->fetch();if(!$r||($kind==='recording'&&$r['status']!=='ready'))json_response(['message'=>'İçerik bulunamadı.'],404);$uid=(int)($viewer['id']??0);if($kind==='clip'&&!v17_can_view_profile((int)$r['streamer_user_id'],$viewer))json_response(['message'=>'Kaynak hesap gizli.'],403);if($uid!==(int)$r[$col]){if(!v17_can_view_profile((int)$r[$col],$viewer))json_response(['message'=>'Bu hesap gizli. Takip isteğinin onaylanması gerekiyor.'],403);if(($r['visibility']??'')==='private')json_response(['message'=>'Bu içeriği yalnızca sahibi görebilir.'],403);if(in_array($r['visibility']??'',['vip','members'],true)&&(!$viewer||!v14_is_paid_member($uid,$r['membership_tier_required']??'plus')))json_response(['message'=>'Aktif VIP üyeliği gerekiyor.'],403);}if($kind==='post'&&!empty($r['clip_id']))v17_content('clip',(int)$r['clip_id'],$viewer);return $r;}
function v17_media_url(string $kind,int $id,string $part='video'):string{return '../backend/api/media/file.php?kind='.$kind.'&id='.$id.'&part='.$part;}
function v17_person(array $r):array{return ['id'=>(int)$r['id'],'username'=>$r['username'],'displayName'=>$r['display_name'],'avatarUrl'=>$r['avatar_url']?:null,'isPrivate'=>(bool)($r['is_private']??0),'publicId'=>$r['public_id']??''];}
function v17_recording(array $r):array{return ['id'=>(int)$r['id'],'recordingId'=>(int)$r['id'],'streamId'=>(int)$r['stream_id'],'userId'=>(int)$r['user_id'],'title'=>$r['title'],'fileUrl'=>v17_media_url('recording',(int)$r['id']),'thumbnailUrl'=>empty($r['thumbnail_url'])?null:v17_media_url('recording',(int)$r['id'],'thumbnail'),'visibility'=>$r['visibility'],'durationSeconds'=>(int)$r['duration_seconds'],'viewCount'=>(int)$r['view_count'],'createdAt'=>$r['created_at'],'username'=>$r['username']??'','streamerName'=>$r['display_name']??'','avatarUrl'=>$r['avatar_url']??null,'category'=>$r['category']??'','description'=>$r['description']??'','processingStatus'=>$r['processing_status']??'ready'];}
function v17_video_mime(string $path):array{$m=(new finfo(FILEINFO_MIME_TYPE))->file($path);$map=['video/mp4'=>'mp4','video/webm'=>'webm','video/quicktime'=>'mov','video/ogg'=>'ogv','application/ogg'=>'ogv'];if(!isset($map[$m]))json_response(['message'=>'MP4, WEBM, MOV veya OGV video seçin.'],415);return [$m,$map[$m]];}
function v17_packages():array{return [100=>1090,500=>4990,1500=>12990,3000=>24990,5000=>39990,12000=>84990];}

function v17_stream(int $id,?array $viewer):array{$r=get_stream_by_id($id);if(!$r)json_response(['message'=>'Yayın bulunamadı.'],404);if(!v17_can_view_profile((int)$r['user_id'],$viewer))json_response(['message'=>'Bu hesap gizli.'],403);return $r;}
function v17_legacy_media(array $rows,string $kind):array{foreach($rows as &$r){foreach(['file_url','video_url','image_url','thumbnail_url'] as $col){if(!empty($r[$col]))$r[$col]=v17_media_url($kind,(int)$r['id'],$col==='thumbnail_url'?'thumbnail':($col==='image_url'?'image':'video'));}}return $rows;}
